mapper.select:
SELECT b.binding_id,hit.source_id,hit.source_version,hit.document_id,hit.title,hit.total_characters
FROM public.nw_runtime_knowledge_bindings b LEFT JOIN LATERAL (
    SELECT s.source_id,s.source_version,v.document_id::text AS document_id,v.title,char_length(c.content) AS total_characters

      AND (#{titleFilter}='' OR strpos(lower(v.title),lower(#{titleFilter}))>0)

      AND (s.source_id,v.document_id::text,s.source_version)>(#{after.sourceId},#{after.documentId},#{after.sourceVersion})

    ORDER BY s.source_id,v.document_id::text,s.source_version LIMIT #{limit}
) hit ON true WHERE b.tenant_id=#{scope.tenant} AND b.binding_id=#{scope.id} AND b.target_digest=#{scope.digest}

SELECT b.binding_id,hit.source_id,hit.source_version,hit.document_id,hit.title,hit.total_characters,hit.content
FROM public.nw_runtime_knowledge_bindings b LEFT JOIN LATERAL (
    SELECT s.source_id,s.source_version,v.document_id::text AS document_id,v.title,char_length(c.content) AS total_characters,
           CASE WHEN c.content IS NULL THEN NULL
                WHEN #{offset}::integer>=char_length(c.content) THEN ''
                ELSE substring(c.content FROM (LEAST(#{offset}::integer,char_length(c.content))+1) FOR #{limit}::integer) END AS content

      AND v.document_id::text=#{documentId}
) hit ON true WHERE b.tenant_id=#{scope.tenant} AND b.binding_id=#{scope.id} AND b.target_digest=#{scope.digest}

SELECT b.binding_id,hit.source_id,hit.source_version,hit.document_id,hit.chunk_id,hit.chunk_index,hit.content,hit.created_at FROM public.nw_runtime_knowledge_bindings b LEFT JOIN LATERAL ( SELECT r.tenant_id, r.binding_id, r.source_id, r.source_version, r.document_id, r.chunk_id, r.chunk_index, c.content, r.created_at FROM public.nw_runtime_knowledge_chunks r JOIN public.knowledge_chunk_values c ON c.tenant_id=r.source_tenant_id AND c.kb_id::text=r.source_id AND c.source_version=r.source_version AND c.document_id::text=r.document_id AND c.id::text=r.chunk_id JOIN public.nw_knowledge_documents document ON document.tenant_id=c.tenant_id AND document.kb_id=c.kb_id AND document.id=c.document_id AND document.deleted_at IS NULL WHERE r.tenant_id=b.tenant_id AND r.binding_id=b.binding_id AND (r.source_id,r.source_version) IN
(#{version.sourceId},#{version.sourceVersion})
AND strpos(lower(c.content),lower(#{query}))>0 AND c.created_at<=#{asOf} AND b.published_at<=#{asOf} AND (#{freshness,jdbcType=TIMESTAMP}::timestamptz IS NULL OR c.created_at>=#{freshness,jdbcType=TIMESTAMP}::timestamptz) ORDER BY CASE WHEN lower(c.content)=lower(#{query}) THEN 0 ELSE 1 END,r.source_id,r.source_version,r.document_id,r.chunk_index,r.chunk_id LIMIT #{limit} ) hit ON true WHERE b.tenant_id=#{tenant} AND b.binding_id=#{id} AND b.target_digest=#{digest}

SELECT NOT EXISTS ( SELECT 1 FROM (VALUES
(#{version.sourceId}, #{version.sourceVersion})
) AS selected(source_id, source_version) WHERE NOT EXISTS ( SELECT 1 FROM public.nw_knowledge_document_versions version JOIN public.nw_knowledge_documents document ON document.tenant_id=version.tenant_id AND document.kb_id=version.kb_id AND document.id=version.document_id AND document.deleted_at IS NULL WHERE version.tenant_id::text=#{tenant} AND version.kb_id::text=selected.source_id AND version.source_version=selected.source_version AND version.status='ready' ) )
